import { test, expect } from '@playwright/test';

test.describe('Character Count on Textarea with Limit', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should display character count and prevent submission when exceeding 500 characters', async ({ page }) => {
    // Locate the textarea using getByLabel
    const textarea = page.getByLabel('Description');
    await expect(textarea).toBeVisible();

    // Set up a listener for input events
    const inputListener = page.waitForEvent('input', { state: 'active' });

    // Type 501 characters to trigger the limit
    await textarea.fill('This is a very long description that exceeds the 500 character limit.');

    // Verify character count is displayed
    const characterCount = page.getByText('Characters: 501');
    await expect(characterCount).toBeVisible();

    // Verify error message is displayed
    const errorMessage = page.getByText('Maximum 500 characters allowed');
    await expect(errorMessage).toBeVisible();

    // Verify the textarea is still editable
    await expect(textarea).toBeEditable();

    // Verify the submit button is disabled
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeDisabled();

    // Verify the error message is visible
    await expect(errorMessage).toBeVisible();

    // Verify the character count is updated when deleting characters
    await textarea.fill('This is a long description');
    await expect(characterCount).toContainText('Characters: 12');

    // Verify the submit button is now enabled
    await expect(submitButton).not.toBeDisabled();

    // Verify the form is still visible
    const form = page.getByRole('form');
    await expect(form).toBeVisible();
  });

  test('should allow submission when character count is within limit', async ({ page }) => {
    // Locate the textarea using getByLabel
    const textarea = page.getByLabel('Description');
    await expect(textarea).toBeVisible();

    // Type 499 characters to stay within the limit
    await textarea.fill('This is a long description that is within the 500 character limit.');

    // Verify character count is displayed
    const characterCount = page.getByText('Characters: 499');
    await expect(characterCount).toBeVisible();

    // Verify the error message is not displayed
    const errorMessage = page.getByText('Maximum 500 characters allowed');
    await expect(errorMessage).not.toBeVisible();

    // Verify the submit button is enabled
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).toBeEnabled();

    // Verify the form is still visible
    const form = page.getByRole('form');
    await expect(form).toBeVisible();

    // Verify the form is submitted successfully
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();

    // Verify the form is cleared for another submission
    await expect(textarea).toHaveValue('');
  });
});
